function updateCamera(){const w=viewport.clientWidth,h=viewport.clientHeight;if(!w||!h||!renderer||!camera)return;const aspect=w/h;camera.left=-scale*aspect;camera.right=scale*aspect;camera.top=scale;camera.bottom=-scale;const look=view==='map'?mapFocus.clone():new THREE.Vector3(0,.7,0);look.y=view==='map'?0:.7;const distance=view==='map'?Math.max(160,scale*2):32;camera.near=.1;camera.far=view==='map'?Math.max(600,distance*3):200;camera.position.set(Math.sin(yaw)*distance,distance,Math.cos(yaw)*distance).add(look);camera.lookAt(look);camera.updateProjectionMatrix();
 // Resizing the canvas reallocates its buffers, so only do it when the size or resolution really changed.
 const size=w+'x'+h+'@'+pixelRatio;if(size!==lastSize){lastSize=size;renderer.setPixelRatio(pixelRatio);renderer.setSize(w,h)}
 // On the map the sun's shadow box follows the camera, and the shadow map is redrawn only when the view changes.
 if(sun){const c=view==='map'?new THREE.Vector3(mapFocus.x,0,mapFocus.z):new THREE.Vector3(),r=view==='map'?Math.min(120,scale*1.5+12):30,k=view==='map'?3:1;sun.position.set(c.x-12*k,24*k,c.z+12*k);sun.target.position.copy(c);sun.target.updateMatrixWorld();const sc=sun.shadow.camera;if(sc.right!==r){sc.left=-r;sc.right=r;sc.top=r;sc.bottom=-r;sc.far=Math.max(200,r*4);sc.updateProjectionMatrix()}}
 renderer.shadowMap.needsUpdate=true;labelsDirty=true}
